mapper.select:
SELECT os.SALE_ORDER_ID, os.USER_ID, os.ORDER_STATUS, os.ORDER_DATE, osi.SALE_ITEM_ID, osi.ORDER_QUANTITY, osi.TOTAL_PRICE, s.TITLE as PRODUCT_TITLE, u.USER_NAME as BUYER_NAME, seller.USER_NAME as SELLER_NAME FROM order_sales os LEFT JOIN order_sales_items osi ON os.SALE_ORDER_ID = osi.SALE_ORDER_ID LEFT JOIN sales s ON osi.SALE_ITEM_ID = s.SALE_ITEM_ID LEFT JOIN users u ON os.USER_ID = u.ID LEFT JOIN users seller ON s.SELLER_ID = seller.ID WHERE os.USER_ID = #{buyerId}
AND os.ORDER_STATUS = #{orderStatus}
ORDER BY os.ORDER_DATE DESC

SELECT os.SALE_ORDER_ID, os.USER_ID, os.ORDER_STATUS, os.ORDER_DATE, osi.SALE_ITEM_ID, osi.ORDER_QUANTITY, osi.TOTAL_PRICE, s.TITLE as PRODUCT_TITLE, u.USER_NAME as BUYER_NAME, seller.USER_NAME as SELLER_NAME FROM order_sales os LEFT JOIN order_sales_items osi ON os.SALE_ORDER_ID = osi.SALE_ORDER_ID LEFT JOIN sales s ON osi.SALE_ITEM_ID = s.SALE_ITEM_ID LEFT JOIN users u ON os.USER_ID = u.ID LEFT JOIN users seller ON s.SELLER_ID = seller.ID WHERE s.SELLER_ID = #{sellerId}
AND os.ORDER_STATUS = #{orderStatus}
AND u.USER_NAME LIKE '%' || #{buyerName} || '%'
AND u.TEL LIKE '%' || #{buyerPhone} || '%'
ORDER BY os.ORDER_DATE DESC

mapper.update:
UPDATE order_sales 
SET ORDER_STATUS = 'COMPLETED'
WHERE SALE_ORDER_ID = #{saleOrderId}

UPDATE order_sales 
SET ORDER_STATUS = #{orderStatus}
WHERE SALE_ORDER_ID = #{saleOrderId}
